const o=(id,label,feedback,art)=>({id,label,feedback,art});
function bio(id,title,observation,answer,why,reasons,reason){return {id,title,observation,art:id,prompt:'Conecta el caso con un grupo.',options:[['living','Está vivo'],['once','Estuvo vivo'],['never','Nunca estuvo vivo']].map(([key,label])=>o(key,label,key===answer?why:key==='living'?'El movimiento o aspecto aislados no bastan para saber si algo vive. Relee el registro.':key==='once'?'Este grupo corresponde a lo que vivió y ya murió. Revisa si eso ocurrió aquí.':'Nunca haber vivido es distinto de haber muerto. Busca la historia de este caso.')),answer,reasons,reason,hint:why};}
const biology=[
 bio('plant','Una planta crece','En este registro, la planta de judía tiene hojas nuevas después de varios días. Recibe agua y luz y toma aire. Sus raíces la mantienen en el mismo lugar.','living','La planta está viva: crece y realiza procesos de vida aunque no camine.',[
 o('growth','Ha crecido y formado hojas nuevas.','El cambio observado durante varios días aporta una evidencia de crecimiento.'),o('green','Es verde.','El color no basta: también hay juguetes verdes y seres vivos de otros colores.'),o('walk','No camina.','Las plantas viven sin caminar; no desplazarse no significa estar muerto.')],'growth'),
 bio('snail','Un caracol en reposo','Sabemos que este caracol está vivo: ayer se alimentó y respiró; hoy descansa sin desplazarse. No lo tocamos ni lo despertamos.','living','El caracol sigue vivo mientras descansa. No necesita desplazarse todo el tiempo.',[
 o('still','Ahora no se desplaza.','Una pausa en el movimiento no determina si un animal vive.'),o('processes','Se alimenta y respira.','Son procesos de vida del caracol, aunque ahora esté quieto.'),o('shell','Tiene una concha.','Una concha vacía también puede permanecer; la forma por sí sola no basta.')],'processes'),
 bio('leaf','Una hoja que ya murió','Esta hoja cayó del árbol, se secó por completo y murió. Antes fue una parte viva del árbol; ahora ya no realiza sus funciones de vida.','once','La hoja estuvo viva como parte del árbol y ahora está muerta. No es algo que nunca vivió.',[
 o('brown','Tiene color marrón.','El color no decide por sí solo: hay cortezas marrones en árboles vivos.'),o('light','Es ligera.','El peso no distingue vivir, haber muerto o nunca haber vivido.'),o('history','Antes fue una parte viva; después murió.','Su historia permite distinguirla de un objeto que nunca estuvo vivo.')],'history'),
 bio('toy','Un coche que se mueve','Este coche de juguete de plástico avanza cuando le damos cuerda. Fue fabricado; no nació ni crece como un ser vivo. El mecanismo mueve sus ruedas.','never','El juguete nunca estuvo vivo. Su mecanismo produce movimiento, no procesos de vida.',[
 o('mechanism','Lo mueve un mecanismo; fue fabricado.','Su movimiento se explica por piezas y energía del mecanismo, no porque viva.'),o('wheels','Se mueve sobre ruedas.','También se mueven objetos que nunca estuvieron vivos. Moverse no es una prueba suficiente.'),o('small','Es pequeño.','Hay seres vivos y objetos de muchos tamaños; el tamaño no resuelve la pregunta.')],'mechanism')
];
const samples={
 clear:o('clear','Plástico transparente','En esta muestra se ve el dibujo con claridad a través de la lámina.','clear'),
 card:o('card','Cartón opaco','Esta muestra tapa el dibujo; no permite verlo a través.','card'),
 cloth:o('cloth','Paño de algodón','En esta prueba dibujada, el paño recoge agua entre sus fibras.','cloth'),
 tray:o('tray','Bandeja de plástico rígido','En esta prueba dibujada, el agua queda sobre la superficie sin absorberse.','tray'),
 foil:o('foil','Lámina de aluminio','En esta prueba dibujada, el agua queda en la superficie, no se absorbe.','foil'),
 mesh:o('mesh','Malla de tela con huecos','A través de los huecos todavía se ve parte del dibujo.','mesh'),
 flexible:o('flexible','Plástico fino y flexible','La muestra dibujada se curva sin romperse al doblarla suavemente.','flexible'),
 wood:o('wood','Bloque de madera rígido','En esta observación, el bloque mantiene su forma y no se curva.','wood'),
 metal:o('metal','Placa de metal rígida','Esta placa gruesa mantiene su forma en la observación; no se curva.','metal')
};
function material(id,title,observation,ids,answer,reasons,reason){return {id,title,observation,art:null,prompt:'Conecta el objetivo con una muestra.',options:ids.map(key=>samples[key]),answer,reasons,reason,hint:reasons.find(r=>r.id===reason).feedback};}
const chemistry=[
 material('window','Una ventana para una maqueta','Queremos ver con claridad un dibujo a través de una ventana de maqueta. Compara las muestras y sus observaciones. No es una ventana para una vivienda.',['card','clear','mesh'],'clear',[
 o('transparent','Permite ver el dibujo con claridad.','Ver el dibujo con claridad es la evidencia de transparencia que buscamos.'),o('color','Me gusta su color.','Una preferencia es válida, pero no demuestra si se puede ver a través.'),o('opaque','Tapa el dibujo.','Taparlo haría lo contrario de la ventana que queremos en esta maqueta.')],'transparent'),
 material('absorb','Recoger unas gotas','Estas son observaciones de una prueba representada, no una prueba que debas hacer. Buscamos una muestra que absorba unas gotas, no que solo las sostenga encima.',['tray','foil','cloth'],'cloth',[
 o('shiny','Brilla.','El brillo no indica si una muestra absorbe agua.'),o('absorbent','El agua entra entre sus fibras.','Que el agua entre entre las fibras indica absorción; sostenerla encima es diferente.'),o('flat','Tiene una superficie plana.','Una superficie plana puede absorber o no. Mira qué ocurre con el agua.')],'absorbent'),
 material('hide','Una tapa para ocultar un dibujo','Queremos que el dibujo no se vea a través de la tapa. Observa lo que permite ver cada muestra, sin cambiarla.',['clear','mesh','card'],'card',[
 o('opaque','No deja ver el dibujo a través.','Impedir ver a través es opacidad: esa es la propiedad que necesitamos.'),o('holes','Tiene huecos.','Los huecos de esta malla dejan ver partes del dibujo.'),o('favorite','Es mi material favorito.','Puedes tener un favorito; esa preferencia no prueba que oculte el dibujo.')],'opaque'),
 material('curve','Un techo curvo de maqueta','Queremos una muestra que pueda curvarse suavemente sin romperse. Las fichas muestran lo observado en estas muestras, no en todos los objetos de cada material.',['wood','flexible','metal'],'flexible',[
 o('heavy','Parece pesada.','El peso aparente no demuestra que se pueda curvar.'),o('rigid','Mantiene esa forma rígida.','La rigidez de esas muestras no cumple el objetivo de hacer una curva suave.'),o('bend','Se curva sin romperse en la observación.','Curvarse sin romperse es la evidencia de flexibilidad que buscamos.')],'bend')
];
export const scienceGames={
 biology:{name:'Biología',title:'Explora los seres vivos',guide:'Mira y lee el registro con un adulto. Conecta el caso con un grupo y después con una evidencia. Una planta puede vivir sin caminar; un juguete puede moverse sin estar vivo.',example:'Ejemplo: un árbol vivo crece y realiza procesos de vida aunque permanezca en el mismo lugar. No lo clasificamos solo por su color.',steps:biology,transfer:'Con un adulto, observa una planta desde un lugar seguro y dibuja cómo es. Otro día puedes volver a mirar. No arranques hojas ni toques animales; también puedes inventar una planta en papel.'},
 chemistry:{name:'Química · materiales',title:'Detectives de materiales',guide:'Cada misión tiene un objetivo. Lee las observaciones, elige una muestra y conéctala con la propiedad que justifica tu elección. Aquí no mezclamos ni probamos sustancias.',example:'Ejemplo: para ver un dibujo a través de una muestra, necesitamos transparencia. El color que más te gusta no demuestra esa propiedad.',steps:chemistry,transfer:'Con un adulto, dibuja un objeto cotidiano y di de qué material está hecho. Puedes mirar papel o una toalla secos, sin romperlos ni probar nada. No uses calor, mezclas, productos de limpieza ni objetos cortantes.'}
};
export const scienceIds=Object.keys(scienceGames);
export const scienceActivities=scienceIds.map(id=>({id,stage:'5y',key:'5y:'+id,area:'Ciencia',type:'digital',label:'6–8 años · lectura acompañada',kind:'interactive',title:scienceGames[id].title,copy:scienceGames[id].name+' · Juego visual de conexiones con cuatro retos. Piloto de iniciación, no una materia completa.',unit:scienceGames[id].title,goal:id==='biology'?'Clasificar casos a partir de observaciones y justificar con una evidencia.':'Relacionar una propiedad observable con un uso concreto de una muestra.',duration:'Una misión o varias, sin tiempo obligatorio',support:'Un adulto lee y acompaña; puedes señalar o usar teclado',transfer:scienceGames[id].transfer}));
export const freshScience=()=>({page:'guide',step:0,answers:Array.from({length:4},()=>({choice:null,reason:null,checked:false}))});
export function checkScience(id,step,choice,reason){const q=scienceGames[id]?.steps[step];if(!q||!Number.isInteger(step)||!q.options.some(o=>o.id===choice)||!q.reasons.some(r=>r.id===reason))throw Error('Conexión de ciencia desconocida');const selected=q.options.find(o=>o.id===choice),evidence=q.reasons.find(r=>r.id===reason);return {correct:choice===q.answer&&reason===q.reason,choiceCorrect:choice===q.answer,reasonCorrect:reason===q.reason,feedback:'Ficha: '+selected.feedback+' Evidencia: '+evidence.feedback+(choice!==q.answer?' Compara la ficha elegida con «'+q.options.find(o=>o.id===q.answer).label+'».':'')};}
